"""Practice: 'Worth remembering', a weekly speech or poem that held someone up, in the spirit of a Sunday column.
Each entry: the scene (who said or carried it, and when it mattered), the words (a memory id, verbatim public domain),
why it is worth having by heart, and how to say it. Writes content/keep.json `remember` and new memory entries.
Run: python3 tools/days/remember.py"""
import json, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
K = os.path.join(ROOT, 'content', 'keep.json'); M = os.path.join(ROOT, 'content', 'memory.json')
k = json.load(open(K)); m = json.load(open(M)); have = {x['id'] for x in m}

def mem(id, title, kind, src, author, work, lines, why, source, tradition="poets", translator=""):
    return {"id": id, "title": title, "kind": kind, "src": src, "author": author, "work": work, "translator": translator, "tradition": tradition, "lines": lines, "why": why, "source": source}

